# Let me check different transformations
input_demo = [
    [0, 0, 7, 0, 0, 6],
    [0, 6, 0, 0, 0, 0],
    [7, 0, 5, 2, 7, 5],
    [0, 2, 1, 0, 8, 0],
    [0, 4, 3, 0, 0, 4],
    [0, 0, 0, 0, 9, 0]
]

q2 = [
    [0, 0, 0, 7, 0, 0],
    [0, 4, 2, 0, 6, 0],
    [0, 3, 1, 5, 0, 7],
    [0, 0, 0, 2, 0, 0],
    [9, 0, 8, 7, 0, 0],
    [0, 4, 0, 5, 0, 6]
]

# Check if Q2 is input rotated 90 degrees
def rotate_90(grid):
    n = len(grid)
    return [[grid[n-1-c][r] for c in range(n)] for r in range(n)]

def rotate_180(grid):
    return rotate_90(rotate_90(grid))

def rotate_270(grid):
    return rotate_90(rotate_180(grid))

def horizontal_flip(grid):
    return [row[::-1] for row in grid]

def vertical_flip(grid):
    return grid[::-1]

def flip_both(grid):
    return [row[::-1] for row in grid[::-1]]

# Transformations
r90 = rotate_90(input_demo)
r180 = rotate_180(input_demo)
r270 = rotate_270(input_demo)
hf = horizontal_flip(input_demo)
vf = vertical_flip(input_demo)
fboth = flip_both(input_demo)

print("Q2:")
for row in q2: print(row)

print("\nRotate 90:")
for row in r90: print(row)

print("\nRotate 180:")
for row in r180: print(row)

print("\nRotate 270:")
for row in r270: print(row)

print("\nHorizontal flip:")
for row in hf: print(row)

print("\nVertical flip:")
for row in vf: print(row)

print("\nFlip both:")
for row in fboth: print(row)

# Let's compare Q2 with various transformations
print("\n\nComparing Q2 to transformations:")
for name, trans in [("90", r90), ("180", r180), ("270", r270), ("HF", hf), ("VF", vf), ("Both", fboth)]:
    match = all(q2[i][j] == trans[i][j] for i in range(6) for j in range(6))
    print(f"{name}: {'MATCH' if match else 'NO MATCH'}")
